const BY_ID: Readonly<Record<string, PackAgentRecord>> = Object.freeze(
  Object.fromEntries(PACK_AGENTS.map((agent) => [agent.id, agent])),
);

export function getPackAgent(agentId: string): PackAgentRecord | undefined {
  return BY_ID[agentId];
}

export function listPackAgents(pack?: string): readonly PackAgentRecord[] {
  if (pack === undefined || pack.length === 0) return PACK_AGENTS;
  return PACK_AGENTS.filter((agent) => agent.pack === pack);
}
